// Format available slots response for Retell
// Expected API response: { slots: ["09:00", "09:30"], duration: 30, provider_name: "Dr. Smith" }
const webhookData = $('Retell Webhook').first().json;
const date = webhookData.body.args.date;
const appointmentType = webhookData.body.args.appointment_type;
const providerName = webhookData.body.args.provider_name || null;

const apiResponse = $input.first().json;
const slots = apiResponse.slots || [];
const duration = apiResponse.duration || 30;
const provider = apiResponse.provider_name || providerName;

const typeDisplay = appointmentType.replace(/_/g, ' ');
const providerDisplay = provider ? ` with ${provider}` : '';

if (slots.length === 0) {
  return [{ json: { result: `I'm sorry, there are no available ${typeDisplay} slots on ${date}${providerDisplay}. Would you like to try a different date?` } }];
}

return [{ json: { result: `Available ${typeDisplay} slots on ${date}${providerDisplay}: ${slots.join(', ')}. Each appointment is ${duration} minutes. Which time would you prefer?` } }];

// Format booking confirmation response for Retell
const args = $('Retell Webhook').first().json.body.args;
const typeNames = {
  new_patient_exam: 'New Patient Exam',
  cleaning: 'Regular Cleaning',
  deep_cleaning: 'Deep Cleaning',
  filling: 'Filling',
  crown_prep: 'Crown Prep',
  consultation: 'Consultation',
  emergency: 'Emergency Visit'
};
const typeName = typeNames[args.appointment_type] || args.appointment_type;

// Format time to 12-hour
const [h, m] = args.time.split(':').map(Number);
const ampm = h >= 12 ? 'PM' : 'AM';
const h12 = h > 12 ? h - 12 : (h === 0 ? 12 : h);
const timeFormatted = `${h12}:${m.toString().padStart(2,'0')} ${ampm}`;

let result = `Your appointment has been booked! Here are the details: ${typeName} on ${args.date} at ${timeFormatted} for ${args.patient_name}`;
if (args.provider_name) result += ` with ${args.provider_name}`;
result += '.';

if (args.email) {
  result += ` A confirmation email has been sent to ${args.email}.`;
}

if (args.is_new_patient) {
  result += ` Since you're a new patient, please arrive 15 minutes early and bring your photo ID, insurance card, and a list of current medications.`;
}

result += ` Is there anything else I can help you with?`;

return [{ json: { result } }];

const args = $('Retell Webhook').first().json.body.args;
let result = `The appointment for ${args.patient_name} on ${args.date} has been cancelled.`;
if (args.reason) {
  result += ` Reason: ${args.reason}.`;
}
result += ' Would you like to reschedule or is there anything else I can help with?';
return [{ json: { result } }];

const args = $json.body.args;
const topic = args.topic;
const lang = ((args.language) || 'en').toString().toLowerCase();

const faqData = {
  en: {
    office_hours: 'Our office hours are Monday to Friday, 8:00 AM to 5:00 PM, and Saturday 9:00 AM to 1:00 PM. We are closed on Sundays. We also have a lunch break from 12:00 PM to 1:00 PM on weekdays.',
    services: 'We offer general dentistry (cleanings, exams, fillings, crowns), cosmetic dentistry (teeth whitening, veneers, bonding), orthodontics (braces and Invisalign), oral surgery (extractions and wisdom teeth removal), pediatric dentistry for children, and emergency dental care with same-day appointments.',
    insurance: 'We work with Generali and Medicover, and we also welcome self-paying patients without insurance.',
    emergency: 'For dental emergencies during our office hours, please call us at +36 20 2576701. For a life-threatening emergency, such as severe bleeding or swelling that affects breathing, call 112 or go to the nearest emergency room immediately. If a tooth has been knocked out, keep it moist in milk or saliva and come in right away.',
    cancellation_policy: 'Please cancel or reschedule at least 24 hours in advance. Cancellations made less than 24 hours before the appointment may incur a fee of 10,000 HUF.',
    new_patient_info: 'If you are a new patient, please arrive 15 minutes early and bring your insurance card and a list of any medications you currently take.',
    location: 'We are located at Dózsa György út 132, 1134 Budapest. You can reach us by phone at +36 20 2576701 or by email at elystrade@gmail.com. You can also find us online at https://sunshine.dental.appointer.hu.',
    payment_options: 'You can pay in cash in Hungarian forint, or by VISA or Mastercard.'
  },
  hu: {
    office_hours: 'Rendelőnk nyitvatartása hétfőtől péntekig 8:00 és 17:00 óra között, szombaton 9:00 és 13:00 óra között. Vasárnap zárva tartunk. Hétköznaponként 12:00 és 13:00 óra között ebédszünetet tartunk.',
    services: 'Szolgáltatásaink: általános fogászat (fogkőeltávolítás, vizsgálatok, tömések, koronák), esztétikai fogászat (fogfehérítés, héjak, bondozás), fogszabályozás (rögzített fogszabályozó és Invisalign), szájsebészet (foghúzás és bölcsességfog-eltávolítás), gyermekfogászat, valamint sürgősségi fogászati ellátás aznapi időpontokkal.',
    insurance: 'A Generali és a Medicover biztosítókkal állunk kapcsolatban, és biztosítás nélküli, önfizető pácienseket is szívesen fogadunk.',
    emergency: 'Fogászati sürgősség esetén nyitvatartási időben hívjon minket a +36 20 2576701 telefonszámon. Életveszélyes helyzetben, például erős vérzés vagy a légzést akadályozó duzzanat esetén, hívja a 112-t, vagy menjen azonnal a legközelebbi sürgősségi ügyeletre. Ha egy fog kiesett, tartsa nedvesen tejben vagy nyálban, és jöjjön be mihamarabb.',
    cancellation_policy: 'Kérjük, legalább 24 órával korábban mondja le vagy módosítsa az időpontját. A 24 órán belüli lemondás esetén 10 000 forint díjat számíthatunk fel.',
    new_patient_info: 'Új páciensként kérjük, érkezzen 15 perccel korábban, és hozza magával a biztosítási kártyáját, valamint a jelenleg szedett gyógyszerei listáját.',
    location: 'Címünk: 1134 Budapest, Dózsa György út 132. Telefonon a +36 20 2576701 számon, e-mailben az elystrade@gmail.com címen érhet el minket. Online is megtalál minket a https://sunshine.dental.appointer.hu oldalon.',
    payment_options: 'Fizethet készpénzzel forintban, vagy VISA, illetve Mastercard bankkártyával.'
  },
  de: {
    office_hours: 'Unsere Öffnungszeiten sind Montag bis Freitag von 8:00 bis 17:00 Uhr und Samstag von 9:00 bis 13:00 Uhr. Sonntags haben wir geschlossen. An Wochentagen machen wir von 12:00 bis 13:00 Uhr Mittagspause.',
    services: 'Wir bieten allgemeine Zahnheilkunde (Zahnreinigung, Untersuchungen, Füllungen, Kronen), ästhetische Zahnheilkunde (Bleaching, Veneers, Bonding), Kieferorthopädie (feste Zahnspangen und Invisalign), Oralchirurgie (Extraktionen und Weisheitszahnentfernung), Kinderzahnheilkunde sowie zahnärztliche Notfallversorgung mit Terminen am selben Tag.',
    insurance: 'Wir arbeiten mit Generali und Medicover zusammen und nehmen auch Selbstzahler ohne Versicherung gerne auf.',
    emergency: 'Bei einem zahnärztlichen Notfall rufen Sie uns während der Öffnungszeiten unter +36 20 2576701 an. Bei einem lebensbedrohlichen Notfall, etwa starken Blutungen oder Schwellungen, die die Atmung beeinträchtigen, wählen Sie 112 oder begeben Sie sich sofort in die nächste Notaufnahme. Wenn ein Zahn ausgeschlagen wurde, halten Sie ihn in Milch oder Speichel feucht und kommen Sie umgehend zu uns.',
    cancellation_policy: 'Bitte sagen Sie Ihren Termin mindestens 24 Stunden im Voraus ab oder verschieben Sie ihn. Bei Absagen weniger als 24 Stunden vor dem Termin kann eine Gebühr von 10.000 HUF anfallen.',
    new_patient_info: 'Als neue Patientin oder neuer Patient kommen Sie bitte 15 Minuten früher und bringen Sie Ihre Versicherungskarte sowie eine Liste Ihrer aktuellen Medikamente mit.',
    location: 'Sie finden uns in der Dózsa György út 132, 1134 Budapest. Sie erreichen uns telefonisch unter +36 20 2576701 oder per E-Mail an elystrade@gmail.com. Online finden Sie uns unter https://sunshine.dental.appointer.hu.',
    payment_options: 'Sie können bar in ungarischen Forint oder mit VISA bzw. Mastercard bezahlen.'
  }
};

const fallback = {
  en: "I'm sorry, I don't have information on that topic. Would you like me to have someone from the office call you back?",
  hu: 'Sajnálom, erről a témáról nincs információm. Szeretné, ha valaki a rendelőből visszahívná Önt?',
  de: 'Es tut mir leid, zu diesem Thema habe ich keine Informationen. Möchten Sie, dass Sie jemand aus der Praxis zurückruft?'
};

const dict = faqData[lang] || faqData.en;
const answer = dict[topic] || faqData.en[topic] || fallback[lang] || fallback.en;

return [{ json: { result: answer } }];

const args = $('Retell Webhook').first().json.body.args;
if (args.callback_requested) {
  return [{ json: { result: "I've saved your information and requested a callback from our office staff. Someone will call you back as soon as possible. Is there anything else I can help with?" } }];
} else {
  return [{ json: { result: "I've saved your information in our records. Is there anything else I can help with?" } }];
}

const args = $('Retell Webhook').first().json.body.args;
const date = args.date;
const providers = $input.all().map(item => item.json);

if (!providers || providers.length === 0) {
  return [{ json: { result: `I'm sorry, there are no doctors available on ${date}. Would you like to try a different date?` } }];
}

const list = providers.map(p => `${p.provider_name} (${p.available_slots} slot${p.available_slots !== 1 ? 's' : ''})`).join(', ');
const firstDoctor = providers[0].provider_name;

return [{ json: { result: `On ${date}, the following doctors are available: ${list}. Do you have a preference, or shall I book you with ${firstDoctor}?` } }];

const a = $('Retell Webhook').first().json.body.args;
const lang = ((a.language) || 'en').toString().toLowerCase();
const type = (a.appointment_type || '').replace(/_/g, ' ');

const T = {
  en: { subject: 'Appointment Confirmation - Sunshine Dental Clinic', h: 'Appointment Confirmed!', dear: 'Dear', intro: 'Your appointment has been confirmed with the following details:', date: 'Date', time: 'Time', type: 'Type', doctor: 'Doctor', tbc: 'Will be confirmed', np: '<strong>New Patient Reminder:</strong> Please arrive 15 minutes early and bring your insurance card and a list of current medications.', cancel: 'If you need to cancel or reschedule, please call us at least 24 hours in advance at +36 20 2576701. Cancellations made less than 24 hours in advance may incur a fee of 10,000 HUF.', see: 'We look forward to seeing you!', regards: 'Best regards,', clinic: 'Sunshine Dental Clinic' },
  hu: { subject: 'Időpont-visszaigazolás – Sunshine Dental Clinic', h: 'Időpontja megerősítve!', dear: 'Kedves', intro: 'Időpontját az alábbi adatokkal megerősítettük:', date: 'Dátum', time: 'Időpont', type: 'Típus', doctor: 'Orvos', tbc: 'Később egyeztetjük', np: '<strong>Emlékeztető új pácienseknek:</strong> Kérjük, érkezzen 15 perccel korábban, és hozza magával a biztosítási kártyáját, valamint a jelenleg szedett gyógyszerei listáját.', cancel: 'Ha le szeretné mondani vagy módosítani szeretné az időpontját, kérjük, hívjon minket legalább 24 órával korábban a +36 20 2576701 telefonszámon. A 24 órán belüli lemondás esetén 10 000 forint díjat számíthatunk fel.', see: 'Várjuk Önt szeretettel!', regards: 'Üdvözlettel:', clinic: 'Sunshine Dental Klinika' },
  de: { subject: 'Terminbestätigung – Sunshine Dental Clinic', h: 'Ihr Termin ist bestätigt!', dear: 'Liebe/r', intro: 'Ihr Termin wurde mit den folgenden Angaben bestätigt:', date: 'Datum', time: 'Uhrzeit', type: 'Art', doctor: 'Arzt/Ärztin', tbc: 'Wird noch bestätigt', np: '<strong>Hinweis für neue Patienten:</strong> Bitte kommen Sie 15 Minuten früher und bringen Sie Ihre Versicherungskarte sowie eine Liste Ihrer aktuellen Medikamente mit.', cancel: 'Wenn Sie Ihren Termin absagen oder verschieben möchten, rufen Sie uns bitte mindestens 24 Stunden im Voraus unter +36 20 2576701 an. Bei Absagen weniger als 24 Stunden vorher kann eine Gebühr von 10.000 HUF anfallen.', see: 'Wir freuen uns auf Ihren Besuch!', regards: 'Mit freundlichen Grüßen,', clinic: 'Sunshine Dental Klinik' }
};

const t = T[lang] || T.en;

let html = '<h2>' + t.h + '</h2>';
html += '<p>' + t.dear + ' ' + a.patient_name + ',</p>';
html += '<p>' + t.intro + '</p>';
html += '<ul>';
html += '<li><strong>' + t.date + ':</strong> ' + a.date + '</li>';
html += '<li><strong>' + t.time + ':</strong> ' + a.time + '</li>';
html += '<li><strong>' + t.type + ':</strong> ' + type + '</li>';
html += '<li><strong>' + t.doctor + ':</strong> ' + (a.provider_name || t.tbc) + '</li>';
html += '</ul>';
if (a.is_new_patient) { html += '<p>' + t.np + '</p>'; }
html += '<p>' + t.cancel + '</p>';
html += '<p>' + t.see + '</p>';
html += '<p>' + t.regards + '<br>' + t.clinic + '</p>';

return [{ json: { sendTo: a.email, subject: t.subject, html } }];

// Reached only when an upstream API call failed (tunnel down, 5xx, timeout).
// Return an explicit error so the agent apologizes and offers a callback
// instead of receiving empty data and fabricating doctors/slots.
return [{ json: { result: "SYSTEM_ERROR: The scheduling system is temporarily unavailable and this request could not be completed. Do NOT invent any appointment, doctor, time, or availability. Apologize to the caller for the technical issue and offer to take their details for a callback." } }];
